import subprocess

def search_pdf(path, terms):
    out = subprocess.check_output(['pdftotext', path, '-']).decode('utf-8')
    print('=== PDF:', path, '===')
    for term in terms:
        print(f'-- Term: {term} --')
        for page_idx, page in enumerate(out.split('\x0c')):
            if term.lower() in page.lower():
                print(f'Page {page_idx+1}:')
                for line in page.split('\n'):
                    if term.lower() in line.lower():
                        print('  ', line.strip())

search_pdf('Birchwood/PackageA/03_Specifications/Spec_312000_Earth_Moving_Rev3.pdf', ['settlement', 'tolerance', 'block c', 'footing'])
search_pdf('Birchwood/PackageA/02_Structural/Design_Basis_Memorandum_Rev2.pdf', ['settlement', 'tolerance', 'block c', 'footing'])
"

